rule "format palo integer fields"
when
  to_string($message.device_vendor) == "PaloAlto"
then
  // Traffic counters
  set_field("bytes_received",   to_long($message.bytes_received));
  set_field("bytes_sent",       to_long($message.bytes_sent));
  set_field("bytes",            to_long($message.bytes));
  set_field("packets",          to_long($message.packets));
  set_field("pkts_received",    to_long($message.pkts_received));
  set_field("pkts_sent",        to_long($message.pkts_sent));
  // Ports
  set_field("src_port",         to_long($message.src_port));
  set_field("dst_port",         to_long($message.dst_port));
  set_field("nat_src_port",     to_long($message.nat_src_port));
  set_field("nat_dst_port",     to_long($message.nat_dst_port));
  // Session & timing
  set_field("session_id",       to_long($message.session_id));
  set_field("elapsed_time",     to_long($message.elapsed_time));
  set_field("repeat_count",     to_long($message.repeat_count));
  set_field("offloaded",        to_long($message.offloaded));
  set_field("app_risk",         to_long($message.app_risk));
  // seqno: stored as string to avoid 64-bit overflow
  // keep seqno as-is (string) — exceeds JS MAX_SAFE_INTEGER
end

rule "format watchguard integer fields"
when
  has_field("device_vendor") AND
  to_string($message.device_vendor) == "WatchGuard"
then
  // Traffic counters
  set_field("bytes_received", to_long($message.bytes_received));
  set_field("bytes_sent",     to_long($message.bytes_sent));
  // Packet counters
  set_field("sent_pkts",      to_long($message.sent_pkts));
  set_field("rcvd_pkts",      to_long($message.rcvd_pkts));
  // Ports
  set_field("src_port",       to_long($message.src_port));
  set_field("dst_port",       to_long($message.dst_port));
  // Session & timing
  set_field("elapsed_time",   to_long($message.elapsed_time));
  // ICMP
  set_field("icmpType",       to_long($message.icmpType));
end

rule "normalize watchguard firewall to common schema"
when
    true
then
    rename_field("src",         "src_ip");
    rename_field("dst",         "dst_ip");
    rename_field("srcPort",     "src_port");
    rename_field("dstPort",     "dst_port");
    rename_field("proto",       "protocol");
    rename_field("disp",        "action");
    rename_field("policy",      "rule_name");
    rename_field("in_if",       "src_zone");
    rename_field("out_if",      "dst_zone");
    rename_field("geo_src",     "src_country");
    rename_field("geo_dst",     "dst_country");
    rename_field("sent_bytes",  "bytes_sent");
    rename_field("rcvd_bytes",  "bytes_received");
    rename_field("sent_pkts",   "pkts_sent");
    rename_field("rcvd_pkts",   "pkts_received");
    rename_field("duration",    "elapsed_time");
    rename_field("app",         "application");
    rename_field("srcPostNAT",  "nat_src_ip");
    rename_field("wg_product",  "device_product");

    let lower_value = lowercase(to_string($message.action));
    set_field("action", lower_value);

    let total_bytes = to_long($message.bytes_sent) + to_long($message.bytes_received);
    set_field("bytes", total_bytes);
end

rule "WG_catalog_networking"
when
    has_field("wg_event_id") &&
    is_not_null(lookup_value("wg-log-catalog-networking", to_string($message.wg_event_id)))
then
    let log_id = to_string($message.wg_event_id);
    let result = lookup("wg-log-catalog-networking", log_id);
    set_field("log_category", "proxy_policy");
    set_field("log_type",  to_string(map_get(result, "log_type")));
    set_field("log_level", to_string(map_get(result, "log_level")));
end

rule "wg extract leef attributes"
when
  to_string($message.device_vendor) == "WatchGuard"
then
  let attrs = key_value(
    value:         to_string($message.wg_raw_attributes),
    delimiters:    "\t",
    kv_delimiters: "="
  );
  set_fields(attrs);

  // Clean up the raw blob after extraction
  remove_single_field("wg_raw_attributes");
end

