rule "wg parse leef header"
when
  contains(to_string($message.message), "LEEF:1.0|WatchGuard")
then
  let raw   = to_string($message.message);
  let parts = split("\\|", raw);

  set_field("wg_product",        to_string(parts[2]));
  set_field("wg_fw_version",     to_string(parts[3]));
  set_field("wg_event_id",       to_string(parts[4]));
  set_field("wg_raw_attributes", to_string(parts[5]));

  // Extract first 4 chars as subsystem prefix
  let eid = to_string(parts[4]);
  set_field("wg_event_prefix",   substring(eid, 0, 4));
end
